import{bV as o,aL as e,u as t,G as l}from"./chunks/framework.DvBUyM1S.js";const g=JSON.parse('{"title":"13个JS一行代码，它们会让你看起来像个大佬","description":"","frontmatter":{"title":"13个JS一行代码，它们会让你看起来像个大佬","date":"2022-03-16T17:29:23.000Z","permalink":"/pages/18fdc2/","categories":["前端开发","JavaScript"],"tags":[null]},"headers":[],"relativePath":"02.开发/06.JavaScript/05.13个JS一行代码，它们会让你看起来像个大佬.md","filePath":"02.开发/06.JavaScript/05.13个JS一行代码，它们会让你看起来像个大佬.md","lastUpdated":1652078909000}'),n={name:"02.开发/06.JavaScript/05.13个JS一行代码，它们会让你看起来像个大佬.md"};function r(s,a,c,i,d,h){return e(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="_13个js一行代码-它们会让你看起来像个大佬" tabindex="-1">13个JS一行代码，它们会让你看起来像个大佬 <a class="header-anchor" href="#_13个js一行代码-它们会让你看起来像个大佬" aria-label="Permalink to &quot;13个JS一行代码，它们会让你看起来像个大佬&quot;">​</a></h1><blockquote><p>说明：本章内容译来源<a href="https://medium.com/dailyjs/13-javascript-one-liners-thatll-make-you-look-like-a-pro-29a27b6f51cb" target="_blank" rel="noreferrer">13-javascript</a>，教程版权归原作者所有。</p></blockquote><h2 id="_1-获取一个随机布尔值-true-false" tabindex="-1">1. 获取一个随机布尔值 (true/false) <a class="header-anchor" href="#_1-获取一个随机布尔值-true-false" aria-label="Permalink to &quot;1. 获取一个随机布尔值 (true/false)&quot;">​</a></h2><p>此函数将使用该<code>Math.random()</code>方法返回一个布尔值（真或假）。 <code>Math.random</code>将创建一个介于 0 和 1 之间的随机数，然后我们检查它是高于还是低于 0.5。这意味着有 50%/50% 的机会判断为真或假。</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447259398609.jpg" alt="" loading="lazy"></p><h2 id="_2-检查提供的日期是否为工作日" tabindex="-1">2. 检查提供的日期是否为工作日 <a class="header-anchor" href="#_2-检查提供的日期是否为工作日" aria-label="Permalink to &quot;2. 检查提供的日期是否为工作日&quot;">​</a></h2><p>使用此方法，您将能够检查您在函数中提供的日期是工作日还是周末。</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447260076793.jpg" alt="" loading="lazy"></p><h2 id="_3-反转字符串" tabindex="-1">3.反转字符串 <a class="header-anchor" href="#_3-反转字符串" aria-label="Permalink to &quot;3.反转字符串&quot;">​</a></h2><p>有几种不同的方法可以反转字符串。split()这是使用、reverse()和方法的最简单的方法之一join()。</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447260901325.jpg" alt="" loading="lazy"></p><h2 id="_4-检查当前选项卡是否在视图-焦点中" tabindex="-1">4.检查当前选项卡是否在视图/焦点中 <a class="header-anchor" href="#_4-检查当前选项卡是否在视图-焦点中" aria-label="Permalink to &quot;4.检查当前选项卡是否在视图/焦点中&quot;">​</a></h2><p><code>document.hidden</code>我们可以使用该属性检查当前选项卡是否在视图/焦点中。 <img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447269177806.jpg" alt="" loading="lazy"></p><h2 id="_5-检查一个数字是偶数还是奇数" tabindex="-1">5.检查一个数字是偶数还是奇数 <a class="header-anchor" href="#_5-检查一个数字是偶数还是奇数" aria-label="Permalink to &quot;5.检查一个数字是偶数还是奇数&quot;">​</a></h2><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447268856339.jpg" alt="" loading="lazy"></p><h2 id="_6-从日期中获取时间" tabindex="-1">6. 从日期中获取时间 <a class="header-anchor" href="#_6-从日期中获取时间" aria-label="Permalink to &quot;6. 从日期中获取时间&quot;">​</a></h2><p>通过使用该<code>.toTimeString()</code>方法并在正确的位置对字符串进行切片，我们可以从我们提供的日期中获取时间，或者获取当前时间。 <img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447268539877.jpg" alt="" loading="lazy"></p><h2 id="_7-将数字截断为固定小数点" tabindex="-1">7.将数字截断为固定小数点 <a class="header-anchor" href="#_7-将数字截断为固定小数点" aria-label="Permalink to &quot;7.将数字截断为固定小数点&quot;">​</a></h2><p>使用该<code>Math.pow()</code>方法，我们可以将数字截断到我们在函数中提供的某个小数点。 <img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447267976762.jpg" alt="" loading="lazy"></p><h2 id="_8-检查元素当前是否处于焦点" tabindex="-1">8.检查元素当前是否处于焦点 <a class="header-anchor" href="#_8-检查元素当前是否处于焦点" aria-label="Permalink to &quot;8.检查元素当前是否处于焦点&quot;">​</a></h2><p><code>document.activeElement</code>我们可以使用该属性检查元素当前是否处于焦点中。 <img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447267739567.jpg" alt="" loading="lazy"></p><h2 id="_9-检查当前用户是否支持触摸事件" tabindex="-1">9. 检查当前用户是否支持触摸事件 <a class="header-anchor" href="#_9-检查当前用户是否支持触摸事件" aria-label="Permalink to &quot;9. 检查当前用户是否支持触摸事件&quot;">​</a></h2><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447267462055.jpg" alt="" loading="lazy"></p><h2 id="_10-检查当前用户是否在苹果设备上" tabindex="-1">10.检查当前用户是否在苹果设备上 <a class="header-anchor" href="#_10-检查当前用户是否在苹果设备上" aria-label="Permalink to &quot;10.检查当前用户是否在苹果设备上&quot;">​</a></h2><p>我们可以<code>navigator.platform</code>用来检查当前用户是否在 Apple 设备上。 <img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447267055128.jpg" alt="" loading="lazy"></p><h2 id="_11-滚动到页面顶部" tabindex="-1">11. 滚动到页面顶部 <a class="header-anchor" href="#_11-滚动到页面顶部" aria-label="Permalink to &quot;11. 滚动到页面顶部&quot;">​</a></h2><p>该<code>window.scrollTo()</code>方法将采用 x 和 y 坐标滚动到。如果我们将它们设置为零和零，我们将滚动到页面顶部。 <strong>注意：IE 不支持 scrollTo() 方法。</strong><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447266844987.jpg" alt="" loading="lazy"></p><h2 id="_12-获取参数的平均值" tabindex="-1">12. 获取参数的平均值 <a class="header-anchor" href="#_12-获取参数的平均值" aria-label="Permalink to &quot;12. 获取参数的平均值&quot;">​</a></h2><p>我们可以使用 <code>reduce</code> 方法来获取我们在此函数中提供的参数的平均值。</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447266231233.jpg" alt="" loading="lazy"></p><h2 id="_13-转换华氏-摄氏" tabindex="-1">13.转换华氏/摄氏 <a class="header-anchor" href="#_13-转换华氏-摄氏" aria-label="Permalink to &quot;13.转换华氏/摄氏&quot;">​</a></h2><p>处理温度有时会令人困惑。这两个函数将帮助您将华氏温度转换为摄氏温度，反之亦然。 <img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/20220213-16447261775569.jpg" alt="" loading="lazy"></p>',32)])])}const m=o(n,[["render",r]]);export{g as __pageData,m as default};
